using System;using System.IO;using System.Collections.Generic;using System.Reflection;using System.Web.Script.Serialization;
namespace TerrainFoundry {public class LauncherTests{
 static object Call(string name,params object[] args){try{return typeof(Launcher).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,args);}catch(TargetInvocationException e){throw e.InnerException;}}
 static void Reject(Action action,string name){try{action();}catch{Console.WriteLine("PASS rejection: "+name);return;}throw new Exception("Not rejected: "+name);}
 public static int Main(string[] args){try{string manifest=File.ReadAllText(args[0]);var parsed=(Dictionary<string,object>)Call("VerifyEnvelope",manifest);if(parsed.ContainsKey("assets")){var packs=(System.Collections.ICollection)parsed["assets"];if(packs.Count==0)throw new Exception("No scenery packs");}Console.WriteLine("PASS signed manifest");var json=new JavaScriptSerializer();var envelope=json.Deserialize<Dictionary<string,object>>(manifest);var bytes=Convert.FromBase64String((string)envelope["payload"]);bytes[bytes.Length/2]^=1;envelope["payload"]=Convert.ToBase64String(bytes);Reject(()=>Call("VerifyEnvelope",json.Serialize(envelope)),"tampered manifest");string root=Path.Combine(Path.GetTempPath(),"terrain-launcher-test-"+Guid.NewGuid());Directory.CreateDirectory(root);Reject(()=>Call("Under",root,"../escape.exe"),"zip traversal");Reject(()=>Call("Under",root,Path.GetPathRoot(root)+"outside.exe"),"absolute zip path");Reject(()=>Call("SafeHash","../bad"),"unsafe digest path");string file=Path.Combine(root,"client.exe");File.WriteAllText(file,"original");string hash=(string)Call("Hash",file);var package=new Dictionary<string,object>{{"files",new Dictionary<string,object>{{"client.exe",hash}}}};Call("CheckInventory",root,package);File.WriteAllText(file,"tampered");Reject(()=>Call("CheckInventory",root,package),"tampered installed client");File.Delete(file);Reject(()=>Call("CheckInventory",root,package),"missing installed client");Directory.Delete(root);Console.WriteLine("PASS launcher trust and local integrity checks");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}}


